#!/usr/bin/env node
// Called from CI when the Playwright suite fails. For every failed screenshot comparison,
// collects the expected/actual/diff triple written by Playwright under test-results/, pushes them
// to the orphan `screenshot-diffs` branch under pr-<N>/run-<id>/, and posts a PR comment that
// shows the images inline and tells reviewers how to accept the new rendering. meta.json in the
// folder records the PR head commit the screenshots were rendered from.
import { existsSync, readdirSync, mkdirSync, copyFileSync, writeFileSync } from 'node:fs';
import { basename, dirname, join } from 'node:path';
import { execSync } from 'node:child_process';
import { mkdtempSync } from 'node:fs';
import { tmpdir } from 'node:os';

const token = must('GITHUB_TOKEN');
const repo = must('GITHUB_REPOSITORY');
const prNumber = must('PR_NUMBER');
const runId = must('GITHUB_RUN_ID');
const headSha = must('HEAD_SHA');
const branch = 'screenshot-diffs';
const relative = `pr-${prNumber}/run-${runId}`;

function must(name) {
  const value = process.env[name];
  if (!value) throw new Error(`missing env var: ${name}`);
  return value;
}

// execSync returns null when a caller passes stdio: 'inherit' (stdout isn't piped), so coerce.
function sh(cmd, opts = {}) {
  return String(execSync(cmd, { stdio: ['ignore', 'pipe', 'inherit'], ...opts }) ?? '').trim();
}

function walk(root) {
  const out = [];
  if (!existsSync(root)) return out;
  for (const entry of readdirSync(root, { withFileTypes: true })) {
    const path = join(root, entry.name);
    if (entry.isDirectory()) out.push(...walk(path));
    else out.push(path);
  }
  return out;
}

// Playwright writes <name>-actual.png next to its -expected.png and -diff.png. Collect by name.
const actuals = walk('test-results').filter((path) => path.endsWith('-actual.png'));
if (actuals.length === 0) {
  console.log('No screenshot diffs found; nothing to publish.');
  process.exit(0);
}

const diffs = actuals.map((actual) => {
  const dir = dirname(actual);
  const base = basename(actual, '-actual.png');
  return {
    name: `${base}.png`, // the baseline file name as toHaveScreenshot('<name>') uses it
    actual,
    expected: join(dir, `${base}-expected.png`),
    diff: join(dir, `${base}-diff.png`),
  };
});

// Clone (or initialize) the orphan branch into a scratch dir.
const scratch = mkdtempSync(join(tmpdir(), 'screenshot-diffs-'));
const remote = `https://x-access-token:${token}@github.com/${repo}.git`;
try {
  sh(`git clone --depth=1 --branch ${branch} ${remote} ${scratch}`, { stdio: 'inherit' });
} catch {
  console.log(`Branch ${branch} does not exist; initializing it.`);
  sh(`git clone --depth=1 ${remote} ${scratch}`, { stdio: 'inherit' });
  sh(`git checkout --orphan ${branch}`, { cwd: scratch, stdio: 'inherit' });
  sh('git rm -rf . || true', { cwd: scratch, stdio: 'inherit' });
  writeFileSync(join(scratch, 'README.md'), 'Screenshot diffs staged for Playwright review. Generated by CI; safe to prune when a PR closes.\n');
  sh('git add README.md', { cwd: scratch, stdio: 'inherit' });
  sh(`git -c user.name='github-actions[bot]' -c user.email='41898282+github-actions[bot]@users.noreply.github.com' commit -m 'Initialize screenshot-diffs branch'`, { cwd: scratch, stdio: 'inherit' });
  sh(`git push origin ${branch}`, { cwd: scratch, stdio: 'inherit' });
}

const dest = join(scratch, relative);
mkdirSync(dest, { recursive: true });
// A screenshot without a committed baseline only has -actual.png (Playwright writes no -expected.png
// or -diff.png then), so remember which images were actually published.
const published = diffs.map(({ name, actual, expected, diff }) => {
  const base = name.replace(/\.png$/, '');
  copyFileSync(actual, join(dest, `${base}-actual.png`));
  const hasExpected = existsSync(expected);
  const hasDiff = existsSync(diff);
  if (hasExpected) copyFileSync(expected, join(dest, `${base}-expected.png`));
  if (hasDiff) copyFileSync(diff, join(dest, `${base}-diff.png`));
  return { name, hasExpected, hasDiff };
});
writeFileSync(join(dest, 'meta.json'), `${JSON.stringify({ headSha, runId }, null, 2)}\n`);

sh(`git config user.name 'github-actions[bot]'`, { cwd: scratch });
sh(`git config user.email '41898282+github-actions[bot]@users.noreply.github.com'`, { cwd: scratch });
sh(`git add ${JSON.stringify(relative)}`, { cwd: scratch, stdio: 'inherit' });
sh(`git commit -m ${JSON.stringify(`PR #${prNumber}: screenshot diffs for run ${runId}`)}`, { cwd: scratch, stdio: 'inherit' });
sh(`git push origin ${branch}`, { cwd: scratch, stdio: 'inherit' });

// Build and post the PR comment. Images come from raw.githubusercontent.com on the orphan branch.
const rawBase = `https://raw.githubusercontent.com/${repo}/${branch}/${relative}`;
const plural = (count, one, many) => `${count} screenshot${count === 1 ? ` ${one}` : `s ${many}`}`;
const changed = published.filter((entry) => entry.hasExpected).length;
const added = published.length - changed;
const summary = [];
if (changed > 0) summary.push(`${plural(changed, 'differs', 'differ')} from the committed baseline`);
if (added > 0) summary.push(`${plural(added, 'has', 'have')} no committed baseline yet`);
let body = `## Screenshot comparison failed\n\n`;
body += `At ${headSha}, ${summary.join(', and ')}. Review each one below.\n\n`;
body += `To accept a new rendering as the baseline, comment \`/accept-screenshot <name>\` on this PR, or \`/accept-screenshot all\` to accept them all at once.\n\n`;
for (const { name, hasExpected, hasDiff } of published) {
  const base = name.replace(/\.png$/, '');
  body += `### \`${name}\`\n\n`;
  // Only link images that were published, so the comment never shows a broken image.
  const cells = [];
  if (hasExpected) cells.push(['Baseline', `![baseline](${rawBase}/${base}-expected.png)`]);
  cells.push([hasExpected ? 'New rendering' : 'New screenshot (no baseline yet)', `![new](${rawBase}/${base}-actual.png)`]);
  if (hasDiff) cells.push(['Diff', `![diff](${rawBase}/${base}-diff.png)`]);
  body += `| ${cells.map(([title]) => title).join(' | ')} |\n|${cells.map(() => '---|').join('')}\n`;
  body += `| ${cells.map(([, image]) => image).join(' | ')} |\n\n`;
  body += `Accept: \`/accept-screenshot ${name}\`\n\n`;
}

const bodyFile = join(scratch, 'comment.md');
writeFileSync(bodyFile, body);
sh(`gh pr comment ${prNumber} --repo ${repo} --body-file ${JSON.stringify(bodyFile)}`, { stdio: 'inherit', env: { ...process.env, GH_TOKEN: token } });

console.log(`Posted ${published.length} screenshot diff(s) for PR #${prNumber}.`);
